  'watch.say.apolloParking': 'Полтора витка вокруг Земли, пока экипаж и Хьюстон всё проверяют. В S-IVB ещё две трети топлива.',
  'watch.beat.tliBurn': 'Разгон к Луне',
  'watch.say.tliBurn': 'S-IVB снова включается над Тихим океаном и работает шесть минут: с 7,8 почти до 10,9 км/с — этого хватает, чтобы долететь до Луны.',
  'watch.beat.tliDone': 'На пути к Луне',
  'watch.say.tliDone': 'Двигатель выключен. «Аполлон-11» уходит от Земли по вытянутому эллипсу, который достигает орбиты Луны и выходит за неё.',
  'watch.beat.transposition': 'Перестроение',
  'watch.say.transposition': 'Четыре створки переходника раскрываются. Коллинз отводит «Колумбию», разворачивает её и возвращается к лунному модулю, ждущему в S-IVB.',
  'watch.beat.apolloDocked': 'Стыковка',
  'watch.say.apolloDocked': 'Штырь «Колумбии» вошёл в приёмный конус «Игла»: корабли сцеплены носом к носу.',
  'watch.beat.extraction': 'Извлечение лунного модуля',
  'watch.say.extraction': 'Пружины выталкивают «Колумбию» и «Игл» из S-IVB. Дальше корабли летят сами.',
  'watch.beat.translunarCoast': 'Перелёт к Луне',
  'watch.say.translunarCoast': 'Три дня полёта к Луне по инерции; Земля всё это время притормаживает корабль. Он медленно вращается, три оборота в час, чтобы Солнце прогревало все стороны по очереди.',
