  'phase.detail.apollo.descentOrbit': 'Снижение к нижней точке орбиты на 15 км: сейчас {moon} км; оттуда начнётся спуск с двигателем.',
  'phase.detail.apollo.descent': '{program}: {galt} м над поверхностью, до места посадки {range} км, {vh} м/с вперёд, {vz} м/с вниз; тяга {thr} %.',
