  'watch.say.lmUndocked': 'Через сто часов полёта «Игл» расстыковывается, и Коллинз осматривает его, пока тот медленно поворачивается за окном. «У орла есть крылья».',
  'watch.beat.doiBurn': 'Переход на орбиту спуска',
  'watch.say.doiBurn': 'За Луной посадочный двигатель «Игла» работает тридцать секунд — всего 23 м/с, — опуская нижнюю точку орбиты до 15 км над подходом к месту посадки.',
  'watch.beat.descentOrbit': 'Орбита спуска',
  'watch.say.descentOrbit': 'Полвитка вниз к нижней точке орбиты. «Колумбия», в нескольких километрах позади и выше, смотрит, как «Игл» уходит вниз.',
  'watch.beat.brakingPhase': 'Спуск с двигателем',
  'watch.say.brakingPhase': 'Посадочный двигатель включается на двенадцать минут — сначала на малой тяге, затем на полной: торможение с 1700 м/с, окнами вниз. Компьютер выдаёт тревоги 1202; Хьюстон даёт «добро».',
  'watch.beat.approachPhase': 'Верхние ворота',
  'watch.say.approachPhase': 'На высоте около 2200 м «Игл» поднимает нос, чтобы экипаж видел, что впереди, — а компьютер ведёт их в кратер, усеянный валунами.',
  'watch.beat.landingPhase': 'Посадка Армстронга',
