  'about.licenceText': 'Код — Apache License 2.0 · уроки, рабочие листы и документация — CC BY 4.0',
  'about.disclaimer': 'Orbitlab — личный учебный проект тайского курсанта ВВС, обучающегося в военно-космической академии, созданный по открытым источникам. Это не продукт Королевских ВВС Таиланда или какой-либо академии; названия и эмблемы ведомств и академий не используются без письменного разрешения.',
