  // ─── строки из src/data/* ────────────────────────────────────────────────
  // Собственные имена — названия носителей, двигателей и коды стран — не
  // переводятся: «Soyuz-2.1a», «Merlin 1D», RU. Переводится то, что является
  // описанием: примечания, названия ступеней, типы аппаратов и космодромы.
  'vehicle.soyuz21a.manufacturer': 'РКЦ «Прогресс»',
  'vehicle.soyuz21b.manufacturer': 'РКЦ «Прогресс»',
  'vehicle.protonm.manufacturer': 'Центр Хруничева',
  'vehicle.angaraa5.manufacturer': 'Центр Хруничева',
  'vehicle.falcon9.manufacturer': 'SpaceX',
  'vehicle.falconheavy.manufacturer': 'SpaceX',
  'vehicle.atlasv551.manufacturer': 'ULA',
  'vehicle.vulcan.manufacturer': 'ULA',
  'vehicle.ariane64.manufacturer': 'ArianeGroup',
  'vehicle.vegac.manufacturer': 'Avio / ESA',
  'vehicle.longmarch2d.manufacturer': 'SAST',
  'vehicle.longmarch3be.manufacturer': 'CALT',
  'vehicle.longmarch5.manufacturer': 'CALT',
  'vehicle.h2a202.manufacturer': 'MHI / JAXA',
  'vehicle.h3.manufacturer': 'MHI / JAXA',
  'vehicle.pslvxl.manufacturer': 'ISRO',
  'vehicle.electron.manufacturer': 'Rocket Lab',
  'vehicle.starship.manufacturer': 'SpaceX',
  'vehicle.soyuz21a.notes': 'Носитель для кораблей «Союз МС» и «Прогресс»: боковые блоки и центральный блок семейства Р-7, третья ступень с РД-0110, прямое выведение.',
  'vehicle.soyuz21b.notes': 'Семейство Р-7; четыре конических боковых блока, горячее разделение третьей ступени, многократно включаемый разгонный блок «Фрегат».',
  'vehicle.protonm.notes': 'Тяжёлый носитель на высококипящих компонентах; разгонный блок «Бриз-М» выполняет многоимпульсное выведение на ГПО и ГСО.',
  'vehicle.angaraa5.notes': 'Модульный кислородно-керосиновый носитель; центральный блок дросселируется до 30 %, пока работают четыре одинаковых блока УРМ-1.',
  'vehicle.falcon9.notes': 'Частично многоразовый; режим возврата первой ступени резервирует топливо на манёвр возврата и посадочное торможение.',
  'vehicle.falconheavy.notes': 'Три блока Falcon 9; центральный блок дросселируется до отделения боковых ускорителей.',
  'vehicle.atlasv551.notes': 'Пять твердотопливных ускорителей, кислородно-керосиновый центральный блок и водородная ступень Centaur с высоким удельным импульсом. РД-180 дросселируется при прохождении максимального скоростного напора.',
  'vehicle.vulcan.notes': 'Первая ступень на метане, до шести твердотопливных ускорителей; Centaur V — водородная ступень для длительных пассивных участков.',
  'vehicle.ariane64.notes': 'Водородный центральный блок с четырьмя твердотопливными ускорителями P120C; ступень Vinci включается повторно для многоорбитальных миссий.',
  'vehicle.vegac.notes': 'Три твердотопливные ступени (P120C, Zefiro 40, Zefiro 9) и многократно включаемая жидкостная ступень AVUM+. P120C используется и как боковой ускоритель Ariane 6.',
  'vehicle.longmarch2d.notes': 'Основной китайский носитель для аппаратов дистанционного зондирования на солнечно-синхронных орбитах: две ступени на высококипящих компонентах, пуски со всех трёх внутренних космодромов.',
  'vehicle.longmarch3be.notes': 'Главный геостационарный носитель Китая: четыре жидкостных боковых ускорителя, две ступени на высококипящих компонентах и многократно включаемая водородная третья ступень с YF-75.',
  'vehicle.longmarch5.notes': 'Тяжёлый носитель Китая: водородный центральный блок с четырьмя кислородно-керосиновыми ускорителями.',
  'vehicle.h2a202.notes': 'Выведен из эксплуатации 28 июня 2025 года после 50 пусков. Водородный центральный блок с LE-7A, два ускорителя SRB-A и многократно включаемая ступень LE-5B; прямой предшественник H3.',
  'vehicle.h3.notes': 'Водородные двигатели LE-9 безгенераторной схемы с отводом газа (expander bleed) и два твердотопливных ускорителя SRB-3.',
  'vehicle.pslvxl.notes': 'Четыре чередующиеся твердотопливные и жидкостные ступени; два из шести боковых ускорителей запускаются в полёте на T+25 с.',
  'vehicle.electron.notes': 'Малый носитель из углепластика с двигателями Rutherford с электронасосной подачей и разгонным блоком Curie.',
  'vehicle.starship.notes': 'Полностью многоразовая двухступенчатая система на метане; горячее разделение, встроенный отсек полезной нагрузки (без головного обтекателя).',
