  'pg.f.twoBody': 'Без J2 орбита кеплерова: узел и перигей неподвижны, а драконический период равен периоду обращения.',
  'pg.crash': 'Перигей ниже поверхности: аппарат на такой орбите врежется в Землю.',
  'pg.kepler': 'Законы Кеплера',
  'pg.k1.title': 'Первый закон Кеплера',
  'pg.k1.text': 'Орбита — эллипс, в одном из фокусов которого находится центр Земли. У этой орбиты e = {e}, поэтому центр Земли смещён от центра эллипса на {c} км.',
  'pg.k2.title': 'Второй закон Кеплера',
  'pg.k2.text': 'Радиус-вектор заметает равные площади за равные промежутки времени — здесь {A} км² в секунду. Поэтому в перигее аппарат летит быстрее всего, а в апогее — медленнее всего.',
  'pg.k3.title': 'Третий закон Кеплера',
  'pg.k3.text': 'Квадрат периода, делённый на куб большой полуоси, одинаков для всех орбит вокруг Земли: T²/a³ = {k} с²/км³ (это 4π²/μ). Здесь T = {T}, a = {a} км.',
  'pg.cannon.title': 'Пушка Ньютона',
  'pg.cannon.lead': 'Воздуха нет: гора выше атмосферы и пушка, стреляющая горизонтально. Чем быстрее выстрел, тем дальше по круглой Земле падает ядро — пока поверхность не начнёт уходить из-под него так же быстро, как оно падает.',
  'pg.cannon.speed': 'Начальная скорость',
