  'pg.cannon.none': 'Задайте скорость и выстрелите.',
  'pg.cannon.impact': 'Ядро падает обратно на Землю в {range} км по поверхности, через {time}.',
  'pg.cannon.orbit': 'Ядро облетает Землю и не падает: это орбита с периодом {period} и высотой до {apogee} км.',
  'pg.cannon.escape': 'Ядро не вернётся: его скорость выше скорости убегания, и оно навсегда покидает Землю.',
  'pg.cannon.note': 'Траектории — точные конические сечения задачи двух тел, без воздуха и без вращения Земли. Гора нарисована в масштабе, но не меньше нескольких пикселей.',
  'pg.cannon.clock': '{time} после выстрела',
