  'use.about.comms': 'Куда направить антенну, чтобы увидеть спутник, какую часть Земли видит спутник, сколько идёт сигнал вверх и вниз и — на уровне «Инженер» — замыкается ли радиолиния.',
  'use.about.eo': 'Что видит камера на спутнике: полосу обзора, наименьшую деталь, расстояние между суточными трассами и насколько далеко достаёт наклон спутника.',
  'use.about.thai': 'Спутники наблюдения Земли Таиланда, спутники Королевских ВВС Таиланда и спутники Thaicom — по открытым источникам. Поставьте орбиту любого из них в модель, чтобы её увидеть.',
