  'thai.theos2.about': 'Национальный спутник наблюдения Земли Таиланда; оператор — GISTDA, изготовитель — Airbus Defence and Space. Его камера различает детали до 50 см; экватор он пересекает, идя на юг, между 10:00 и 10:30 по местному времени, а трасса повторяется каждые 26 суток.',
  'thai.theos.about': 'Первый спутник наблюдения Земли Таиланда; оператор — GISTDA, изготовитель — EADS Astrium: чёрно-белая съёмка 2 м и цветная 15 м, пересечение экватора на юг в 10:00, трасса повторяется каждые 26 суток (369 витков). В 2026 году всё ещё работает, в продлённой миссии.',
  'thai.napa1.about': 'Первый спутник Королевских ВВС Таиланда: кубсат 6U, изготовленный нидерландской ISISPACE, с камерой разрешением около 39 м — для разведки и наблюдения. Выведенный на орбиту высотой около 500 км, он опустился примерно до 310 км.',
  'thai.napa2.about': 'Второй спутник Королевских ВВС Таиланда, тоже кубсат 6U от ISISPACE, с камерой разрешением около 5 м и светодиодным маяком для слежения. Летал по солнечно-синхронной орбите 520 × 540 км и сошёл с орбиты 5 июля 2026 года.',
  'thai.thaicom4.about': 'IPSTAR — первый в мире высокопроизводительный спутник широкополосной связи, выведенный для Thaicom в 2005 году в точку 119,5° в. д.; сейчас им управляет National Telecom (NT).',
  'thai.thaicom6.about': 'Спутник телевидения и связи Thaicom в точке 78,5° в. д., общей с Thaicom 8; запущен в январе 2014 года ракетой Falcon 9.',
  'thai.thaicom7.about': 'Половина спутника: Thaicom использует 14 из 28 транспондеров аппарата, который AsiaSat эксплуатирует как AsiaSat 6, в точке 120° в. д.',
  'thai.thaicom8.about': 'Спутник Thaicom в точке 78,5° в. д. рядом с Thaicom 6, запущенный в мае 2016 года ракетой Falcon 9, первая ступень которой села на плавучую платформу в океане.',
  // R02: real satellites (src/ui/orbit/sky-panel.ts, src/orbit/real-sky.ts)
  'sky.modes': 'Что показано',
  'sky.mode.orbit': 'Ваша орбита',
  'sky.mode.sky': 'Реальные спутники',
  'sky.title': 'Реальные спутники',
  'sky.lead': 'Спутники там, где они есть, по элементам орбит, по которым их отслеживают, в прогнозе SGP4 — теории, для которой эти элементы и составлены. Часы идут с этого момента.',
