  'sky.group.thai': 'Спутники Таиланда',
  'sky.group.gnss': 'Навигация (ГНСС)',
  'sky.group.weather': 'Метеоспутники',
  'sky.group.imaging': 'Спутники съёмки Земли',
  'sky.group.debris': 'Обломки: Fengyun-1C',
  'sky.group.imported': 'Ваш файл',
  'sky.about.stations': 'Пилотируемые станции и то, что летает с ними или пристыковано к ним: {n} объектов.',
  'sky.about.thai': 'THEOS-2, THEOS, NAPA-1 и спутники Thaicom. Что делает каждый из них, с источниками, — в разделе «Зачем нужны спутники» вашей орбиты.',
  'sky.about.gnss': 'Навигационные группировки — GPS, ГЛОНАСС, Galileo и BeiDou: {n} спутников.',
  'sky.about.weather': 'Метеоспутники на низких полярных и на геостационарной орбитах: {n}.',
  'sky.about.imaging': 'Спутники исследования природных ресурсов из открытого каталога (группа CelesTrak): гражданские и коммерческие съёмочные спутники, такие как Landsat, Sentinel, Pléiades, WorldView и THEOS, радиолокационные спутники и военные, чьи элементы орбит опубликованы, например китайские Yaogan — правительственные спутники дистанционного зондирования, вероятно используемые и для военной разведки: всего {n}. Спутников, элементы орбит которых не публикуются, здесь нет.',
  'sky.about.debris': 'Fengyun-1C, китайский метеоспутник на орбите 845 × 865 км, был уничтожен испытанием противоспутниковой ракеты 11 января 2007 года. NASA назвало образовавшееся облако самым сильным загрязнением низкой околоземной орбиты; большинство обломков находятся на орбитах, где продержатся десятилетия и века. {n} из них до сих пор в каталоге.',
  'sky.about.imported': 'Элементы орбит из вашего файла: {n}. Файл прочитан на этой странице и никуда не отправлен.',
