  'pass.shadow': 'Не виден: в тени Земли',
  'pass.faint': 'Слишком далеко, чтобы увидеть глазом',
  'pass.note': 'Время — по часам вашего устройства ({zone}). Углы места — видимые: рефракция в атмосфере поднимает спутник у горизонта примерно на полградуса, поэтому он восходит на несколько секунд раньше, чем без атмосферы. Спутник виден, когда он освещён Солнцем, а Солнце опустилось под ваш горизонт на 6° и более. Яркость — в звёздных величинах (меньше — ярче; самые яркие звёзды около 0–1), оценка по стандартной звёздной величине спутника из таблицы наблюдателей М. Маккантса, для спутников, которые в ней есть; блики панелей бывают ярче.',
  'pass.bright': 'ярче всего около {mag} звёздной величины',
