  'unc.axes': '± км вдоль орбиты (одно стандартное отклонение) в зависимости от числа суток от эпохи набора элементов; белая линия — текущий момент.',
  'unc.lead': 'Набор элементов ничего не сообщает о своей точности, поэтому это оценка: типичная ошибка каталога для такой орбиты на эпоху, растущая примерно на {growth} км в сутки, в основном вдоль орбиты. На низких орбитах, где торможение атмосферой трудно предсказать, и у маневрирующих спутников реальные ошибки больше. Источники:',
  'unc.passTiming': 'время ±{s} с (оценка)',
  // M01: close approaches, screened against the catalogue
  'conj.title': 'Тесные сближения',
  'conj.lead': 'Каждый объект из групп каталога и из прочитанного файла рассчитывается по SGP4 рядом с этим спутником, начиная с момента на экране: когда он проходит ближе всего, на каком расстоянии и — по оценённой неопределённости обоих наборов элементов и заданному вами размеру пары — вероятность столкновения, как оценка.',
