  'conj.more': 'R {r} · T {tr} · N {n} · {v} км/с · неопределённость {s1} и {s2} км',
  'conj.note': 'Собственная ошибка набора элементов — от сотен метров до километров (оценка выше), поэтому это сближения, заслуживающие внимания, а не будущие столкновения: когда 10 февраля 2009 года столкнулись Iridium 33 и «Космос-2251», их сближение было лишь 152-м в такой же проверке за тот день.',
  'conj.case': 'Тот же расчёт по опубликованным данным о сближении при том столкновении даёт опубликованные вероятности: 2,7 × 10⁻⁵¹ с ковариациями военных, 9,3 × 10⁻⁴ с оценкой орбиты Iridium, 3,2 × 10⁻² с её консервативной ковариацией (опубликовано: 2,6 × 10⁻⁵¹, 1,0 × 10⁻³, 3,3 × 10⁻²).',
  'conj.zone': 'Время — по часам вашего устройства ({zone}).',
  'conj.show': 'Показать',
  'conj.hide': 'Скрыть',
  'conj.tcaMark': 'сближение',
  'conj.planeScale': 'плоскость сближения',
  'conj.planeNote': 'Плоскость, перпендикулярная относительной скорости в момент наибольшего сближения: второй объект в {miss} м, вокруг него круг суммарного радиуса пары ({r} м), вокруг этого — суммарная неопределённость положения, показанная на уровнях 1σ и 3σ (1σ: {s1} м на {s2} м). Вероятность столкновения — доля неопределённости, попадающая в круг.',
  'conj.planeShown': 'Время перенесено на пять минут раньше сближения; в 3D видна орбита второго объекта и точка встречи.',
  'cdm.title': 'Сообщение о сближении (CDM)',
  'cdm.lead': 'Об опасном сближении оператор узнаёт из сообщения о сближении (CCSDS 508.0-B-1) с неопределённостью положения каждого объекта по данным слежения. Откройте такое сообщение в текстовой форме (KVN), чтобы получить вероятность по его собственным неопределённостям, а не по грубым оценкам выше. Файл читается на странице и никуда не отправляется.',
  'cdm.read': 'Открыть сообщение (.cdm, KVN)',
  'cdm.tooBig': 'больше, чем бывает сообщение о сближении',
  'cdm.error': '{file} не удалось прочитать как сообщение о сближении: {reason}',
  'cdm.objects': '{a} и {b}, от {from}',
  'cdm.radiusGiven': 'Суммарный радиус (м), как в сообщении',
  'cdm.result': 'Наибольшее сближение {tca}: {miss} м при {v}; вероятность столкновения {p} — по неопределённостям из сообщения.',
  'cdm.theirs': 'Вероятность, указанная в сообщении: {p} ({method}).',
  // M02: overflights of a place by the group on screen
  'over.title': 'Пролёты над {place}',
  'over.lead': 'Когда спутники выбранной группы пролетают над местом, начиная с момента на экране: каждый пролёт с наибольшей высотой не ниже выбранной, угол отклонения от надира, под которым камера должна смотреть на место, и освещено ли место солнцем (оптической камере это нужно, радару — нет).',
  'over.minEl': 'Наибольшая высота не ниже',
