  'cases.lead': 'Лист вопросов для печати и отдельно ключ ответов по реальному случаю, с опубликованными данными и физикой этого приложения: столкновение Iridium 33 и «Космоса-2251», ступень «Чанчжэн-5B», выведшая «Тяньхэ», THEOS-2 над Бангкоком.',
