  'over.night': 'в темноте',
  'over.north': 'на север',
  'over.south': 'на юг',
  'over.more': '{km} км от трассы · местное солнечное время {lst} · время ±{s} с (оценка)',
  'over.note': 'Пролёт — это возможность увидеть место, а не съёмка: для неё нужна заявка оператора, а оптической камере — ясное небо. Учитываются только спутники с опубликованными элементами орбит.',
  'over.canOnly': 'Только когда его прибор может снять это место',
  'over.sensorNote': 'Может ли прибор снять место, оценивается в высшей точке пролёта по данным оператора: полоса обзора неподвижной камеры, наибольший угол отклонения от надира у манёвренной, углы падения и сторона обзора у радара. Камере нужен дневной свет; радар видит ночью и сквозь облака. Лучшее разрешение — в его самом детальном режиме.',
  'sensor.line': '{instrument} · {kind} · лучшее разрешение {res} м',
