  'result.epoch': 'набор элементов от {date}',
  'result.area': '{v} м²',
  'result.radius': 'радиус {v} м',
  'result.sw': 'Космическая погода на {date}',
  'result.invalid': 'Введите число больше нуля.',
  'result.fixFirst': 'Исправьте отмеченные значения, чтобы запустить расчёт.',
  'mv.b.available': 'Запас Δv в баках',
  'mv.b.used': 'Израсходовано топлива',
  'mv.b.left': 'Осталось в баках',
  'mv.b.engineOn': 'Работа двигателя',
  'mv.b.short': 'Топлива не хватает: плану недостаёт {dv}, баки пустеют во время импульса {n}.',
  'mv.b.long': 'Импульс {n} длится {time} — заметную часть витка: такой долгий импульс лишь приближённо можно считать мгновенным, как в плане.',
  'pg.life.label': 'Орбита интерактивной модели, {pe} × {ap} {u}, i = {i}°',
  'pg.view.porkchop': 'Диаграмма Δv',
  'pg.view.porkchopLabel': 'Диаграмма porkchop: суммарная Δv каждого перехода к цели по времени старта и времени перелёта',
  'pc.title': 'Суммарная Δv по времени старта и перелёта',
  'pc.x': 'Старт через, мин',
  'pc.y': 'Время перелёта, мин',
  'pc.cell': 'старт через {dep} мин, перелёт {tof} мин: {dv} {u}',
  'pc.empty': 'здесь перехода нет',
  'pc.hint': 'Каждая точка — переход, найденный решением задачи Ламберта; белый круг — самый дешёвый, красный — спланированный. Щёлкните, чтобы выбрать другой.',
  'pc.none': 'Выберите «Сближение» в разделе «Манёвры», чтобы увидеть его диаграмму.',
  'tour.cannonFalls.title': 'Пушка Ньютона: ядро падает',
  'tour.cannonFalls.text': 'Ньютон представил пушку на горе такой высоты, что воздух уже не тормозит ядро. Выпущенное со скоростью 4 км/с, ядро падает на Землю, как всякое брошенное тело, — но Земля круглая, и падает оно далеко за изгибом её поверхности.',
  'tour.cannonOrbits.title': 'Пушка Ньютона: ядро падает вокруг Земли',
  'tour.cannonOrbits.text': 'Быстрее — и ядро падает ещё дальше. При скорости около 7,8 км/с на этой высоте поверхность уходит из-под ядра ровно так же быстро, как оно падает, и оно никогда не упадёт. Это и есть орбита: ядро всё время падает — но вокруг Земли.',
  'tour.iss.title': 'Международная космическая станция',
  'tour.iss.text': 'На высоте около 420 км станция облетает Землю примерно за полтора часа — больше пятнадцати раз в сутки — со скоростью 7,7 км/с. Плоскость её орбиты наклонена к экватору на 51,6°, поэтому станция пролетает над всеми местами между 51,6° северной и южной широты, где живёт большинство людей на Земле.',
  'tour.hohmann.title': 'Гомановский переход: два импульса',
  'tour.hohmann.text': 'С низкой орбиты на геостационарную высоту — два импульса. Первый, по направлению полёта, вытягивает круг в эллипс, дальний конец которого достигает 35 786 км; через пол-оборота, наверху, второй скругляет орбиту. Это переход Вальтера Гомана (1925) — самый экономичный двухимпульсный путь между двумя круговыми орбитами: с 500 км он стоит около 3,8 км/с и занимает чуть больше пяти часов.',
  'tour.molniya.title': '«Молния»: медленно наверху',
  'tour.molniya.text': 'Советская орбита для связи на Крайнем Севере: вытянутый эллипс с апогеем на высоте 39 750 км над северным полушарием. Цветные секторы — равные промежутки времени (второй закон Кеплера): перигей на юге аппарат проскакивает меньше чем за час, а остальные одиннадцать часов из двенадцати проводит высоко над севером. При наклонении 63,4° — критическом — сжатие Земли не поворачивает линию апсид, и апогей остаётся на севере.',
  'tour.geo.title': 'Геостационарная орбита: спутник стоит на месте',
  'tour.geo.text': 'На высоте 35 786 км над экватором спутник делает оборот за звёздные сутки — 23 ч 56 мин, — за то же время, за которое Земля поворачивается один раз. С Земли он кажется неподвижным: его трасса — одна точка. Этот спутник стоит над 78,5° в. д., в позиции спутников Thaicom, поэтому антенну можно закрепить неподвижно.',
  'tour.sso.title': 'Солнечно-синхронная орбита: каждый день в одно время',
  'tour.sso.text': 'Спутники наблюдения Земли летают почти через полюса, под углом около 98° к экватору. Экваториальное утолщение Земли поворачивает плоскость их орбиты примерно на градус в сутки — так же быстро, как Земля обходит Солнце, — поэтому они пересекают экватор каждый день в одно и то же местное время (здесь 10:30, на север), и освещение на всех снимках одинаковое. С каждым витком трасса смещается на запад: Земля поворачивается под орбитой.',
  // S04: offline or online data (ui/data-dialog.ts, main.ts)
