  'life.method.cowell': 'Полные уравнения движения (все силы)',
  'life.methodNote': 'Средние элементы усредняют каждый виток и охватывают десятилетия за секунды, но учитывают только J2 и сопротивление. Полные уравнения учитывают все силы и все короткопериодические колебания, но требуют минуты и больше на моделируемый год; используйте их для месяцев. Плотность воздуха — по модели NRLMSISE-00, которую ECSS рекомендует для расчёта торможения орбит, для солнечного потока и геомагнитной активности каждого дня; её погрешность ECSS оценивает примерно в 15 %. Сопротивление зависит от площади, массы и C_x; предложенные значения — оценки для класса полезной нагрузки. С измеренной солнечной активностью модель сводит с орбиты спутники известной формы в пределах 25 % от действительного времени входа, обычно раньше; постоянный уровень может ошибаться втрое и больше.',
