  'build.eng.preview.view': 'Чертёж',
  'build.eng.preview.stacked': 'В сборе',
  'build.eng.preview.apart': 'Разнесённо',
  'build.eng.preview.note': 'Вид сбоку в масштабе по тем же данным, что использует стенд, аэродинамическая труба и проверка готовности, — ракета на стенде в её текущем виде, а не исходная из каталога. Выберите деталь (форму или подпись), чтобы увидеть её характеристики.',
  'build.eng.preview.pick': 'Выберите деталь на чертеже, чтобы увидеть характеристики и испытать её.',
  'build.eng.preview.length': 'Длина',
