  'build.eng.stand.refuse.vacuumOnly': '{engine} — высотный двигатель. Его сопло рассчитано на почти полную пустоту космоса и в воздухе не работало бы на расчётном режиме, поэтому характеристик у земли для него не публикуют и в модели их нет: в воздухе она показала бы полную пустотную тягу, а это неверно. Его испытывают только в барокамере.',
  'build.eng.stand.refuse.solidShutdown': 'Твердотопливный двигатель нельзя выключить: зажжённый заряд горит, пока не выгорит всё топливо.',
