  'build.eng.stand.endCutoff': 'Выключен по команде на {t}, в баках осталось {left} топлива; спад тяги закончился к {end}.',
  'build.eng.stand.firedAt': 'Двигатель работал на {p} % полной тяги.',
  'build.eng.stand.compare': 'Модель рядом с данными',
  'build.eng.stand.compareLead': 'Опубликованные характеристики из каталога рядом с тем, что измерил стенд. На полной тяге установившаяся тяга модели в пустоте и у земли совпадает с каталожной по построению, как и пустотный удельный импульс; там, где столбцы расходятся, модель отходит от данных.',
