  'build.eng.stand.row.ispPad': 'Удельный импульс при {p}',
  'build.eng.stand.notPublished': 'не опубликовано',
  'build.eng.stand.notData': 'заглушка',
  'build.eng.stand.note.pad': 'При таком давлении характеристик никто не публикует: модель берёт тягу между значениями у земли и в пустоте пропорционально давлению воздуха, а массовый расход не меняется.',
  'build.eng.stand.note.ispSL': 'Модель берёт за данные пустотные тягу и удельный импульс, сохраняет заданный ими массовый расход при любом давлении и вычисляет удельный импульс у земли из тяги у земли и этого расхода. Если пара значений у земли в каталоге не согласована с пустотной, два удельных импульса у земли различаются: разница заложена в данных, а не в испытании.',
  'build.eng.stand.note.throttled': 'Стенд работал на {p} % тяги, поэтому его тяга не сравнивается с характеристиками на полной тяге; удельный импульс сравнивается, потому что в модели он от уровня тяги не зависит.',
  'build.eng.stand.note.solidMean': 'Каталожная тяга твердотопливного двигателя — это средняя тяга за опубликованное время работы; средняя тяга стенда — полный импульс, делённый на время работы.',
  'build.eng.stand.note.solidPeak': 'Опубликованную максимальную тягу твердотопливного двигателя каталог хранит как отношение к средней: в {f} раза больше. Максимум на стенде наступает сразу после выхода на режим и чуть ниже опубликованного, потому что часть заряда выгорает, пока двигатель разгорается.',
  'build.eng.stand.note.peakVacuum': 'Опубликованный максимум — пустотная величина: испытайте двигатель в барокамере, чтобы сравнить с ним показание стенда.',
  'build.eng.stand.note.vacuumOnly': 'Значения у земли для высотного двигателя в данных — заглушки, а не измерения, и модель их никогда не использует.',
  'build.eng.stand.plots': 'Тяга, расход и удельный импульс во времени',
  'build.eng.stand.noCurves': 'Запуска не было, поэтому и кривых нет.',
  'build.eng.stand.transients': 'Выход на режим и спад тяги крупным планом',
  'build.eng.stand.transientsNote': 'И то и другое — оценки модели, одинаковые для всех жидкостных или всех твердотопливных двигателей, а не измеренные переходные процессы этого двигателя: полная тяга через {s} с после запуска, а после выключения тяга спадает с постоянной времени {tau} с и полностью исчезает за {span} с. Топливо на оба процесса берётся из баков, а удельный импульс модель всё время держит постоянным.',
  'build.eng.stand.transientsOwn': 'И то и другое задано для этого двигателя в его данных, а не измерено: полная тяга через {s} с после запуска, а после выключения тяга спадает с постоянной времени {tau} с и полностью исчезает за {span} с. Топливо на оба процесса берётся из баков, а удельный импульс модель всё время держит постоянным.',
