  'build.eng.tunnel.invalidPayload': 'Сохранённые входные данные аэродинамической трубы недопустимы. Очистите или исправьте их перед использованием графика.',
  'build.eng.tunnel.lead': 'Поставьте ракету {name} в трубу и проведите её через все числа Маха и углы атаки, которые ей могут встретиться. Труба снимает аэродинамику полёта 6DOF его же кодом.',
  'build.eng.tunnel.estimate': 'Эти таблицы — оценки модели, а не измерения: ни у одной ракеты в приложении нет данных продувок. Они рассчитаны по компоновке ракеты методом тонкого тела с учётом вязкого поперечного обтекания, а сопротивление задано одной общей кривой ракеты-носителя для всех ракет, поэтому стабилизаторы и форма носа здесь ничего не меняют — как и в обеих моделях полёта.',
