  'build.eng.tunnel.mapLabel': 'Карта «{q}» по числам Маха от {m0} до {m1} и углам атаки от {a0}° до {a1}°: от {min} до {max}.',
  'build.eng.tunnel.keys': 'Наведите указатель на клетку или выберите карту и двигайтесь стрелками, чтобы прочитать значение.',
  'build.eng.tunnel.cmNote': 'Относительно центра масс. Выше нуля (красный цвет) момент доворачивает нос дальше в сторону угла — это неустойчиво; ниже нуля (синий) он возвращает нос навстречу потоку — это устойчиво.',
  'build.eng.tunnel.xcpNote': 'Точка приложения боковой аэродинамической силы, отсчитанная от вершины носа. Позади центра масс она стабилизирует ракету; впереди него — отворачивает нос от потока.',
  'build.eng.tunnel.envelope': 'Заштрихованы клетки за пределами 15°, на которые рассчитаны таблицы: там их продолжает только теория поперечного обтекания, и полёт отмечает такой угол как выход за границы применимости.',
  'build.eng.tunnel.table': 'Числа в виде таблицы',
