  'build.eng.review.flyLead': 'Откроет раздел «Запуск» с этой ракетой и полезной нагрузкой {payload} на орбиту «{orbit}» с космодрома {site}, старт в {time}: ровно та миссия, что проверена здесь.',
  'build.eng.review.flyWait': 'Дождитесь проверки миссии в её нынешнем виде.',
