  'build.eng.tab.staging': 'Распределение Δv',
  'build.eng.staging.title': 'Оптимальное распределение Δv по ступеням',
  'build.eng.staging.lead': 'Как разделить Δv ракеты между ступенями, чтобы она подняла наибольшую полезную нагрузку при своей стартовой массе. Для ступеней с заданными удельным импульсом и относительной массой конструкции ответ даёт классическое решение методом множителей Лагранжа (Curtis, Orbital Mechanics for Engineering Students). Решение идеальное: без гравитационных и аэродинамических потерь и только для последовательных ступеней.',
  'build.eng.staging.from': 'Взять ступени у',
  'build.eng.staging.fromBench': 'Ракета на стенде: {name}',
  'build.eng.staging.fromNote': 'Подставит удельный импульс в пустоте и относительную массу конструкции каждой ступени, собственную идеальную Δv ракеты и её полезную нагрузку (для настоящей ракеты — половину паспортной на низкую орбиту). Дальше любое значение можно изменить.',
  'build.eng.staging.strapOnsOut': 'Боковые блоки (групп: {n}) не учитываются: они работают одновременно с центральной ступенью, а этот метод такого не описывает.',
