  'build.eng.staging.note': 'Отношение масс — масса связки при включении ступени, делённая на её массу при выключении этой ступени. Доля полезной нагрузки — полезная нагрузка, делённая на стартовую массу. Всё идеально: удельный импульс в пустоте, без гравитационных и аэродинамических потерь.',
  'build.eng.staging.noteSplit': 'В оптимуме никакой небольшой перенос Δv с одной ступени на другую не увеличивает полезную нагрузку.',
