  'build.eng.staging.col.optimum': 'Оптимум',
  'build.eng.staging.col.real': 'Настоящая ракета',
  'build.eng.staging.why': 'Оптимум даёт первой ступени {opt}, а у настоящей ракеты на неё приходится {real}. Оптимум не учитывает потерь и считает относительную массу конструкции каждой ступени неизменной. Одного он не видит: гравитационные потери настоящей ракеты зависят от того, как разделена Δv. Первая ступень с большой тягой быстро проходит крутой участок подъёма и плотную атмосферу, а верхние ступени с малой тягой, включённые раньше, на ещё крутой траектории теряли бы на гравитации больше. Это одна из причин дать первой ступени больше, чем даёт оптимум без потерь.',
  'build.eng.staging.fairingNote': 'Настоящая ракета поднимает на первой ступени ещё и обтекатель ({m}), которого оптимум не учитывает.',
  'build.eng.staging.compareEdited': 'Ваши ступени теперь отличаются от ступеней {name}: сравнение сделано для её собственных, и её распределение на вашей кривой не показано.',
  'build.eng.staging.plot': 'Доля полезной нагрузки и распределение Δv',
  'build.eng.staging.plotTwo': 'Для двух ступеней здесь строится доля полезной нагрузки в зависимости от того, как Δv поделена между ними.',
  'build.eng.staging.plotLead': 'Две ступени делят {dv}: по горизонтали — доля первой ступени, по вертикали — доля полезной нагрузки. Кривая падает до нуля там, где ступени понадобилось бы больше, чем позволяет её конструкция.',
  'build.eng.staging.plotTitle': 'Доля полезной нагрузки, %',
  'build.eng.staging.plotCurve': 'доля полезной нагрузки',
  'build.eng.staging.optimum': 'оптимум',
  'build.eng.staging.real': 'настоящая ракета',
  'build.eng.staging.bad.count': 'Выберите от 1 до {stages} ступеней.',
  'build.eng.staging.bad.isp': 'Ступень {n}: удельный импульс должен быть от {min} до {max} с.',
