  'build.eng.staging.bad.payload': 'Полезная нагрузка должна быть от {min} до {max} кг.',
  'build.eng.staging.whyLess': 'Оптимум даёт первой ступени {opt}, а у настоящей ракеты на неё приходится {real} — меньше. Оптимум не учитывает потерь и считает относительную массу конструкции каждой ступени неизменной; конструкторы этой ракеты разделили иначе — по причинам, которых этот метод не видит. Вблизи оптимума полезная нагрузка меняется мало: сравните доли полезной нагрузки.',
  'build.eng.staging.plotRead': 'Оптимум: {opt} на первой ступени, доля полезной нагрузки {pi}.',
  'build.eng.staging.plotReadReal': 'Настоящая ракета: {real} на первой ступени, доля полезной нагрузки {pi} на этой кривой.',
  'build.eng.tab.sizing': 'Расчёт ракеты',
  'build.eng.size.title': 'Рассчитать ракету-носитель',
  'build.eng.size.lead': 'Задайте полезную нагрузку, орбиту и космодром, а для каждой ступени — двигатель, относительную массу конструкции, диаметр и тяговооружённость. Страница рассчитает ступени под ту Δv, которую планировщик миссии закладывает на эту орбиту, распределит её по ступеням, как при оптимальном распределении, поставит столько двигателей, сколько нужно для заданной тяговооружённости, и соберёт ракету из деталей.',
  'build.eng.size.name': 'Ракета на {payload}',
