  'build.eng.size.extraNote': 'Добавляется к запасу планировщика — на потери, которые у небольшой или медленной ракеты больше заложенных. При 0 ракета рассчитывается точно по границе планировщика.',
  'build.eng.size.twLiftoff': 'Тяговооружённость при старте',
