  'build.eng.size.refusedKept': 'Рисунок и таблица показывают последнюю ракету, которую удалось рассчитать.',
  'build.eng.size.designDv': 'Расчётная Δv',
  'build.eng.size.dvParts': 'На орбиту «{orbit}» с космодрома {site}: затраты на выведение по планировщику {cost} (скорость орбиты и его запас на потери за вычетом {credit}, которые даёт вращение Земли), плюс его резерв {margin} и ваша добавка {extra}.',
  'build.eng.size.dvNote': 'Расчётная Δv — это запас планировщика, нижняя граница того, что настоящие ракеты теряют при выведении; реальной ракете может понадобиться больше. Ракета на 1 т, рассчитанная так, не дошла до орбиты — кончилось топливо — и ей потребовалось около +500 м/с, в основном из-за обтекателя, который она несёт далеко в работу второй ступени. Проверка готовности выполнит её пробный полёт.',
