  'build.refuse.unknownPart': 'Этой детали нет в каталоге.',
  'build.refuse.badFactor': 'Ступень можно удлинить или укоротить только на положительную долю.',
  'build.refuse.badCount': 'Число вне допустимых пределов: от 1 до 50 двигателей на ступени, от 1 до 12 боковых блоков в группе.',
  'build.refuse.badIgnition': 'Боковые блоки можно включить не позже чем через 600 с после старта.',
  'build.refuse.lumpedRecount': 'Эта запись — не один настоящий двигатель: каталог записывает несколько двигателей одной строкой, поэтому их число задано и изменить его нельзя.',
  'build.refuse.solidMotor': 'Твердотопливный двигатель — это сам корпус и заряд: его нельзя заменить другим двигателем, и жидкостная ступень его принять не может. Меняйте ступень или боковой блок целиком.',
  'build.refuse.familyMismatch': 'Этот двигатель работает не на том топливе, что залито в баки. Выберите двигатель на том же топливе.',
  'build.refuse.vacuumEngineOnPad': 'Высотный двигатель нельзя включать на старте: его сопло работает только высоко над атмосферой. Первой ступени и боковым блокам нужны двигатели для работы у земли.',
  'build.refuse.tooManyGroups': 'Первая ступень несёт не более 4 групп боковых блоков.',
