  // --- D06 track B: the satellite builder (build.sat.*) ---
  'build.sat.tpl.napa2': 'NAPA-2 (кубсат 6U)',
  'build.sat.tpl.napa2.about': 'Второй спутник наблюдения Земли ВВС Таиланда, кубсат формата 6U: опубликованные масса 10 кг и размеры, орбита, на которой он летал, без двигателя, солнечные элементы на корпусе. Нагрузка, аккумулятор, радио и камера — оценки.',
  'build.sat.tpl.theos2': 'Съёмочный спутник класса THEOS-2',
  'build.sat.tpl.theos2.about': 'Спутник наблюдения Земли, подобный THEOS-2 агентства GISTDA: солнечно-синхронная орбита 621 км, снимки 0,5 м, срок службы десять лет, X-диапазон 140 Мбит/с (eoPortal). Масса 425 кг — цифра eoPortal и оценка: в другом источнике 417 кг. Камера — пример, дающий опубликованные 0,5 м, а не её настоящая конструкция.',
  'build.sat.tpl.earthObs.about': 'Класс спутников наблюдения Земли из каталога (например, «Ресурс-П», WorldView) на солнечно-синхронной орбите 600 км. Масса, двигатель и размеры — типичные для класса; остальное — оценки.',
  'build.sat.tpl.comsat.about': 'Класс геостационарных спутников связи из каталога (например, «Экспресс-АМ», Intelsat) с апогейным двигателем для подъёма с переходной орбиты. Масса, двигатель и размеры — типичные для класса; остальное — оценки.',
  'build.sat.tpl.weather.about': 'Класс геостационарных метеоспутников из каталога (например, «Электро-Л», GOES) с апогейным двигателем. Масса, двигатель и размеры — типичные для класса; остальное — оценки.',
  'build.sat.tpl.navigation.about': 'Класс навигационных спутников из каталога (например, «Глонасс-К», GPS III) на орбите ГЛОНАСС высотой 19 130 км. Масса, двигатель и размеры — типичные для класса; остальное — оценки.',
  'build.sat.tpl.science.about': 'Класс научных спутников из каталога (например, «Спектр-РГ», Fermi) на полярной орбите 800 км. Масса, двигатель и размеры — типичные для класса; остальное — оценки.',
