  'build.sat.warn.noSso': 'На такой высоте солнечно-синхронной орбиты нет: используется заданное наклонение {i}.',
  'build.sat.warn.power': 'К концу срока службы солнечная батарея даёт на свету {have}, а нагрузке нужно {need}: требуется {area} элементов.',
  'build.sat.warn.battery': 'Аккумулятор не выдержит нагрузку в самой длинной тени: нужно {need}, есть {have}.',
  'build.sat.warn.batteryDeep': 'Самая длинная тень разряжает аккумулятор на {depth} — глубже допустимых {dod}; чтобы уложиться в них, нужна ёмкость {need}.',
  'build.sat.warn.dv': 'Баков хватает на {available}, а бюджет Δv требует {required} — на {short} больше.',
  'build.sat.warn.geoNoEngine': 'В геостационарном кольце без двигателя спутник не удержит свою позицию и не уйдёт из кольца в конце службы, как требует IADC (на {dh} выше).',
  'build.sat.warn.linkNone': 'Радиолиния на {rate} не замыкается: запас {margin}. С обычным запасом {floor} она пропускает {max}.',
  'build.sat.warn.linkThin': 'Радиолиния на {rate} замыкается с запасом всего {margin} — меньше обычных {floor}. С запасом {floor} она пропускает {max}.',
  'build.sat.warn.wheel': 'Маховики накапливают {have}, а наихудшие возмущения набирают за виток {need}.',
  'build.sat.warn.ballisticLow': 'Баллистический коэффициент {b} ниже, чем у любого тела на орбите: проверьте массу и размеры.',
  'build.sat.warn.ballisticHigh': 'Баллистический коэффициент {b} — как у листа фольги: атмосфера быстро сведёт его с орбиты.',
  'build.sat.warn.aperture': 'Апертура {d} размывает детали мельче {diff}: разрешение пикселей {gsd} недостижимо.',
  'build.sat.warn.swathHorizon': 'Поле зрения камеры выходит за горизонт: сузьте его — увеличьте фокусное расстояние или уменьшите число пикселей.',
  'build.sat.warn.cameraRate': 'Камера при съёмке выдаёт {camera}, а радиолиния передаёт {link}: снимки ждут сеанса связи на борту, как у любого съёмочного спутника.',
  'build.sat.est.dragArea': 'Площадь сопротивления {area} (баллистический коэффициент {b}) — оценка: средняя площадь сечения корпуса и крыльев при беспорядочном вращении. На эту же площадь давит солнечный свет в методе Коуэлла при расчёте времени жизни; метод средних элементов световое давление не учитывает.',
  'build.sat.est.power': 'Энергетика рассчитана на самую длинную тень за год при одинаковой нагрузке на свету и в тени, потоке 1361 Вт/м² и солнечной батарее в состоянии на конец срока службы.',
  'build.sat.est.torques': 'Моменты — оценки для наихудшего случая: отклонение от вертикали 45°, Солнце светит перпендикулярно, атмосфера как в перигее, магнитное поле как над полюсом. Солнечная активность: {level}.',
  'build.sat.est.link': 'Радиолиния рассчитана на наихудшую дальность — от апогея до станции при минимальном угле места, а самый длинный сеанс — при пролёте прямо над станцией; КИП антенны спутника принят 55 % (оценка).',
  'build.sat.est.cycles': 'Не больше {n} циклов заряда в год, по одному на виток; на орбите с сезонами без тени их меньше.',
  'build.sat.est.noEngine': 'Без двигателя орбиту ничто не поддерживает: атмосфера её понижает, а расчёт времени жизни показывает, когда спутник сойдёт с орбиты.',
  'build.sat.est.reentry': 'Конец службы заложен как управляемый сход: перигей понижается до 50 км (Hull, New SMAD, гл. 30). Спутнику, который атмосфера сведёт с орбиты в течение 25 лет после конца миссии, это не нужно: см. время жизни.',
  'build.sat.est.geoKeeping': 'В геостационарной позиции бюджет компенсирует дрейф наклонения 0,85° в год (оценка, дающая 45,5 м/с в год по TU Delft) и 1,33 м/с в год по долготе.',
  'build.sat.est.camera': 'Камера снимает из перигея. Для разрешения при отклонении от надира и дифракционного предела нет открытого примера для проверки — только самосогласованность; поток данных указан без сжатия.',
  'build.sat.est.eccentric': 'Орбита эллиптическая: камера, моменты и атмосфера рассчитаны для перигея, радиолиния — для апогея, сеанс связи — как на круговой орбите.',
  'build.sat.store.fileInvalid': 'Спутник из этого файла эта версия рассчитать не может, поэтому ничего не импортировано.',
