  'build.sat.store.toRocket': 'В этом файле ракета «{name}»: она сохранена и открыта в конструкторе ракет.',
  'build.sat.store.invalid': 'Эту конструкцию нельзя сохранить: одно из значений выходит за допустимые пределы.',
