  'build.sat.lead': 'Начните с настоящего спутника или класса спутников и меняйте его орбиту, энергетику, двигатель, радио и камеру. Все цифры пересчитываются по мере ввода — тень, нужные солнечная батарея и аккумулятор, запас Δv, радиолиния с Землёй, детали, которые видит камера, — а то, что не работает, сказано словами. Отправьте его в раздел «Орбита», чтобы узнать, сколько он продержится, или запустите его на ракете в разделе «Запуск».',
