  'build.req.unmet': 'не выполнено: {list}',
  'build.req.st.neverSeen': 'объект не виден',
  'build.req.st.noContact': 'нет связи',
  'build.req.st.noEngine': 'нет двигателя',
  'build.req.st.notProvenLife': 'не доказано, что продержится',
  'build.req.st.notProvenDown': 'не доказано, что сойдёт вовремя',
  'build.req.note.binds': 'Что ограничивает: требование, ближе всех подошедшее к пределу, — как доля допустимого или имеющегося на борту, которую требует орбита (100 % — на пределе; больше — не выполнено).',
  'build.req.note.gsd': 'Камера: фокусное расстояние и апертура, нужные для заданного разрешения, по сравнению с камерой шаблона. Больше 100 %: проект получает камеру крупнее, но масса остаётся массой шаблона.',
  'build.req.note.rate': 'Наибольшая скорость и данные в сутки: с передатчиком шаблона, до минимального угла места. Открытый проект получает передатчик, подобранный под заданный объём данных.',
  'build.req.note.power': 'Солнечная батарея и аккумулятор: на самую длинную тень за год, по аналитической формуле при худшем угле β; если съёмка только днём, полезная нагрузка в тени выключена. Стенд подбирает их заново по тени, найденной численно вдоль орбиты, при всех включённых нагрузках.',
  'build.req.note.life': 'Время жизни: наименьшая высота, на которой спутник продержится весь срок, найдена расчётом времени жизни при фиксированном уровне солнечной активности с точностью ±5 км. Ниже неё двигатель должен компенсировать торможение (показано Δv); в последних 10 км поиска не доказано, что спутник продержится.',
  'build.req.note.disposal': 'Δv на увод: от снижения перигея до высоты, с которой спутник сходит вовремя (слишком мало), до управляемого схода по Халлу с перигеем 50 км (достаточно). Вывод делается по верхней величине.',
  'build.req.note.held': 'С двигателем стенд закладывает в бюджет Δv компенсацию торможения на весь срок и управляемый сход в конце, а 25 лет до схода отсчитывает от расчётной орбиты; таблица же разрешает орбите, которая продержится весь срок за счёт одного торможения, считать срок плюс 25 лет. Поэтому стенд может сказать «нет» там, где строка говорит «да».',
  'build.req.note.revisit': 'Наибольший интервал: наибольший перерыв между съёмками за один цикл повторения трассы, найденный её перебором; для дневной съёмки — в сезон даты расчёта.',
  'build.req.note.mass': 'Масса, платформа и площадь сопротивления остаются от шаблона.',
  'build.req.designName': 'От требований: {cycle}, {h}',
  'build.req.open.noContact': 'Эта орбита не проходит ни над одной отмеченной станцией, поэтому никакой передатчик не сбросит данные.',
  'build.req.open.outside': 'Стенд не может принять проект для этой орбиты. Вне допустимого диапазона: {field}.',
  'build.req.cmp.title': 'Орбита {cycle} на высоте {h} рядом со стендом',
  'build.req.cmp.lead': 'Каждая величина: как в строке и как её рассчитал спутниковый стенд для открытого проекта; = совпадает, ≠ отличается, с причиной.',
  'build.req.cmp.changed': 'Проект на стенде изменён после того, как была открыта эта строка: в столбце «Стенд» — проект в том виде, в каком его открыли. Откройте строку снова, чтобы сравнить заново.',
  'build.req.cmp.other': 'Сейчас на стенде другой проект: в столбце «Стенд» — проект этой строки в том виде, в каком его открыли.',
  'build.req.cmp.figure': 'Величина',
