  'build.req.cmp.mass': 'Масса с полными баками',
  'build.req.cmp.why.eclipse': 'В строке — аналитическая формула при худшем β; стенд находит тень численно вдоль орбиты.',
  'build.req.cmp.why.array': 'Подобрана стендом заново: по тени, найденной численно вдоль орбиты, при всех включённых нагрузках.',
  'build.req.cmp.why.battery': 'Подобран стендом заново: по тени, найденной численно вдоль орбиты, при всех включённых нагрузках.',
  'build.req.cmp.why.rate': 'В строке — передатчик шаблона; на стенде — передатчик проекта, подобранный под заданный объём данных.',
  'build.req.cmp.why.txRaised': 'Нужная мощность передатчика меньше наименьшей допустимой на стенде (1 мВт), поэтому она поднята до 1 мВт: запас растёт.',
  'build.req.cmp.life': 'Время жизни и правило 25 лет проверьте на вкладке «Время жизни» стенда: там учитывается площадь сопротивления самого проекта, а она меняется вместе с размером солнечной батареи.',
