  'setup.notation': 'Обозначения динамики полёта',
  'setup.notation.iso': 'ISO 1151 (международный)',
  'setup.notation.gost': 'ГОСТ 20058-80 (российский)',
  'setup.notation.note': 'По умолчанию на русском используется ГОСТ 20058-80, на английском и тайском — ISO 1151. Явный выбор стандарта заменяет это значение. Им следуют обозначения, оси связанной системы и знаки всех угловых скоростей и углов, которые показывает программа, ручные команды угловых скоростей и CSV. Таблица — в разделе «Физика и источники».',
  'dlg.physics.notation': 'Обозначения',
  'dlg.physics.notationText': 'Обозначения соответствуют ISO 1151 (число Маха — ISO 80000) или ГОСТ 20058-80, как выбрано в режиме инженера; по умолчанию на русском действует ГОСТ, на английском и тайском — ISO. В обоих стандартах ось x связанной системы направлена к носу; в ISO ось y направлена вправо, ось z — вниз, в ГОСТ ось y — вверх, ось z — вправо. Поэтому угловая скорость кабрирования положительна как q в ISO и как ωz в ГОСТ, а поворот носа вправо даёт +r в ISO, но −ωy в ГОСТ. Угловые скорости и углы показаны в осях и знаках действующего стандарта; определения ниже — его.',
