  'watch.mission.soyuzMs25Blurb': '23 марта 2024 г.: через два дня после автоматической отмены на T−20 с та же ракета уходит в полёт. Двухсуточная схема, стыковка с «Причалом» 25 марта.',
  'watch.payload.soyuzMs25': '«Союз МС-25» (Новицкий, Василевская, Дайсон)',
  'watch.mission.falcon9Orbcomm2': 'ORBCOMM-2: первая посадка ступени',
  'watch.mission.falcon9Orbcomm2Blurb': '22 декабря 2015 г., ночью: одиннадцать спутников на 620 км, и впервые первая ступень орбитальной ракеты возвращается и садится — на площадку LZ-1.',
  'watch.payload.orbcomm2': '11 спутников ORBCOMM OG2',
  'watch.mission.angaraA5Flight1': '«Ангара-А5»: первый полёт',
  'watch.mission.angaraA5Flight1Blurb': '23 декабря 2014 г., Плесецк: новая тяжёлая ракета выводит двухтонный макет на геостационарную высоту четырьмя включениями «Бриза-М» за девять часов.',
  'watch.payload.angaraDummy': 'Габаритно-весовой макет (2 042 кг)',
  'watch.mission.h2aHayabusa2': 'H-IIA: старт «Хаябусы-2»',
  'watch.mission.h2aHayabusa2Blurb': '3 декабря 2014 г., Танэгасима: зонд за образцами астероида на опорную орбиту 250 км. Полёт — до опорной орбиты; повторное включение к Рюгу не моделируется.',
  'watch.payload.hayabusa2': '«Хаябуса-2»',
  'watch.mission.falcon9Demo2': 'Demo-2: первый экипаж Crew Dragon',
  'watch.mission.falcon9Demo2Blurb': '30 мая 2020 г., LC-39A: Хёрли и Бенкен на Crew Dragon — первый экипаж, стартовавший из США с 2011 года. Без обтекателя: капсула сама служит носом ракеты. Ступень садится в море.',
  'watch.payload.demo2': 'Crew Dragon «Индевор» (Хёрли, Бенкен)',
  'watch.mission.sputnik1': 'Спутник-1: первый спутник',
  'watch.mission.sputnik1Blurb': '4 октября 1957 г., Байконур: Р-7 без верхней ступени выводит на орбиту шар массой 84 кг, а вместе с ним и центральный блок. Начинается космическая эра.',
  'watch.payload.sputnik1': 'ПС-1, «Спутник-1»',
  'watch.mission.vostok1': '«Восток-1»: Гагарин',
  'watch.mission.vostok1Blurb': '12 апреля 1961 г., с того же старта: Юрий Гагарин, первый человек в космосе, один виток вокруг Земли за 108 минут.',
  'watch.payload.vostok1': '«Восток-1» (Гагарин)',
  'watch.mission.mr3': '«Меркурий-Редстоун-3»: Шепард',
  'watch.mission.mr3Blurb': '5 мая 1961 г., мыс Канаверал: Алан Шепард на «Фридом-7», первый американец в космосе, 15-минутный полёт по дуге до 187 км и приводнение в Атлантике.',
  'watch.payload.mr3': '«Фридом-7» (Шепард)',
  'watch.mission.apollo11': '«Аполлон-11»: к Луне',
  'watch.mission.apollo11Blurb': '16 июля 1969 г., стартовый комплекс 39A: Армстронг, Олдрин и Коллинз на «Сатурне-5» — пять F-1, ступени S-II и S-IVB, опорная орбита 186 км.',
  'watch.payload.apollo11': '«Колумбия» и «Игл» («Аполлон-11»)',
