  'dlg.physics.loop': 'Контур стабилизации',
  'dlg.physics.loopText': 'В модели 6DOF автомат стабилизации каскадный: рассогласование по углу, умноженное на K_θ, даёт заданную угловую скорость, не выше той, с которой ракета ещё успевает остановиться на цели; рассогласование по скорости, умноженное на K_ω, даёт угловое ускорение, ограниченное тем, что исполнительные органы могут создать против аэродинамики; I·ε + ω × Iω — момент, который запрашивается у управляющих двигателей, затем у РСУ. На участке выведения разгрузка поворачивает команду к потоку, когда угол к нему нагрузил бы конструкцию. Инспектор контура стабилизации в режиме инженера (в панели 6DOF) показывает каждый блок в полёте и в повторе.',
