  'eq.intro.engineer': 'Уравнения, которые модель решает в этот момент, в обозначениях {standard}, с подставленными значениями; в режиме инженера добавлены тяга, орбита, гравитация, вращение и управление. Зелёная отметка означает, что записанное движение удовлетворяет уравнению.',
