  'freq.assumptions': 'Линеаризовано численно по собственной модели полёта (жёсткой или с колебаниями топлива и изгибом P05), с дискретизацией 0,01 с и экстраполятором нулевого порядка, через запаздывание приводов качания, режекторный фильтр и упреждающую компенсацию; устойчивость — по собственным числам замкнутого контура. Не учтены: ограничения скорости, ускорения и хода приводов, РСУ при работающих двигателях и перекрёстные связи каналов. При неустойчивых полюсах разомкнутого контура запасы читаются с учётом критерия Найквиста.',
