  'nav.note': 'Истинное минус оценка, на фоне ±3σ фильтра (штрих): координаты и скорость — по радиали, трансверсали и бинормали истинной орбиты; углы — в осях выбранной нотации. Фильтр Калмана в ошибках с 21 переменной (ошибки координат, скорости, ориентации, смещений и масштабов датчиков). Воздушные данные (набегающий поток для разгрузки) остаются истинными; планирование и управление манёврами на орбите пока используют истинное состояние.',
