  // --- G08 ---
  'setup.faults.title': 'Отказы системы управления (G08)',
  'setup.faults.note': 'Отказ исполнительных органов, датчиков или бортовой ЦВМ автомата стабилизации в заданный момент — или воспроизведение реальной аварии; видно, спасает ли полёт FDIR. Пустой список — ничего не отказывает, и полёт прежний бит в бит.',
  'setup.faults.preset': 'Сценарий',
  'setup.faults.preset.none': 'Нет',
  'setup.faults.preset.custom': 'Свой список',
  'setup.faults.preset.proton2013': 'Протон-М, 2 июля 2013',
  'setup.faults.preset.ariane501': 'Ariane 501, 4 июня 1996',
  'setup.faults.preset.vega17': 'Vega VV17, 17 ноября 2020',
  'setup.faults.preset.falconGimbal': 'Сопло в упоре (гипотетически)',
  'setup.faults.presetNote.proton2013': 'Три датчика угловых скоростей канала рыскания были установлены перевёрнутыми. Обратная связь по скорости раскачивала ракету вместо демпфирования; сразу после старта она ушла по рысканию и упала рядом со стартовым комплексом. Все три датчика ошибались одинаково, поэтому никакое голосование не помогает. Полёт на Протоне-М; модель инвертирует рыскание во всех трёх ИИБ со старта.',
  'setup.faults.presetNote.ariane501': 'Обе инерциальные системы отсчёта работали на одном ПО; незащищённое преобразование 64-битного числа в 16-битное переполнилось примерно в H0+37 с. Обе отключились; бортовая ЦВМ приняла их диагностические слова за углы и отклонила сопла до упора, и ракета разрушилась под аэродинамической нагрузкой. Полёт на Ariane 6 — ближайшей ракете парка; модель выводит из строя все три ИИБ в T+36,7 с.',
  'setup.faults.presetNote.vega17': 'При сборке перепутали кабели двух рулевых приводов сопла верхней ступени AVUM. С первого включения ступени сопло отклонялось против каждой команды, и ступень закувыркалась. Монитор FDIR видит, что привод отрабатывает полученную команду, и ничего не замечает. Модель инвертирует сопло AVUM+, как только летит 4-я ступень.',
  'setup.faults.presetNote.falconGimbal': 'Не авария: сопло одного из внешних двигателей Falcon 9 уходит в упор в T+60 с. Без FDIR остальные восемь борются с ним; с FDIR монитор привода выключает этот двигатель за 0,3 с, и остальные продолжают управлять — так Falcon 9 долетел после отказа двигателя в полёте CRS-1 в 2012 году.',
  'setup.faults.otherVehicle': 'Сценарий рассчитан на {vehicle}.',
  'setup.faults.fdir': 'FDIR (обнаружение, локализация и парирование отказов)',
  'setup.faults.fdirNote': 'Голосование ИИБ (2 из 3); модель каждого рулевого привода и выключение двигателя при отказе его сопла; изоляция неисправных двигателей ориентации; резервная ЦВМ, принимающая управление через 0,2 с. Выключено — ЦВМ читает только ИИБ 1 и ничего не контролирует.',
  'setup.faults.empty': 'Отказов в списке нет.',
