  // --- G01 ---
  'setup.explicit.title': 'Наведение на участке выведения: PEG и IGM (G01)',
  'setup.explicit.note': 'Первая ступень летит по программе тангажа, как прежде; ступени вне атмосферы может вести явный закон наведения — к перигею орбиты выведения: его высоте и скорости, горизонтальному полёту и плоскости орбиты.',
  'setup.explicit.law': 'Наведение верхних ступеней',
  'setup.explicit.standard': 'Штатное (замкнутое, закон линейного тангенса)',
  'setup.explicit.peg': 'PEG — явное наведение «Спейс Шаттла»',
  'setup.explicit.igm': 'IGM — итеративное наведение «Сатурна V»',
  'setup.explicit.about.standard': 'Собственное замкнутое наведение симулятора: вертикальный канал по закону линейного тангенса с ограничениями и обратная связь по рысканию в плоскость.',
  'setup.explicit.about.peg': 'Переносит требуемое приращение скорости из цикла в цикл и уточняет его по прогнозу состояния на момент выключения, проинтегрированному с учётом J2 и оставшихся ступеней.',
  'setup.explicit.about.igm': 'Решает задачу в замкнутом виде в системе координат прогнозируемой точки выключения, со средним ускорением тяготения сейчас и в цели; последние двадцать секунд наводит только по скорости.',
  'setup.explicit.cycle': 'Такт наведения (с)',
  'setup.explicit.engage': 'Включается, когда запущена следующая ступень или первая вышла из атмосферы (ниже 100 Па выше 70 км); если оставшихся ступеней не хватает до цели, управление возвращается штатному наведению. В 6-DOF также снимает разгрузку по нагрузкам со скоростью 4 °/с, а не сразу при 500 Па.',
  'loop.tab.guidance': 'Наведение',
  'guide.none': 'В этом полёте нет явного наведения. PEG или IGM выбираются в настройке (режим инженера).',
  'guide.note': 'Явный закон против штатного: время и скорость до цели, заданный тангаж и орбита, прогнозируемая на момент выключения (штрих — цель). Само выключение по-прежнему решает участок выведения по достигнутой орбите.',
