  'watch.say.onTheMoon': 'Двадцать один с половиной час на базе Спокойствия: через шесть с половиной часов после посадки Армстронг ступает на поверхность, за ним Олдрин; два с половиной часа они ставят приборы и собирают 22 кг грунта.',
  'watch.beat.lunarLiftoff': 'Старт с Луны',
