  'watch.beat.tpiBurn': 'Начало конечного этапа',
  'watch.say.tpiBurn': 'Когда «Колумбия» поднимается на 26,6° над горизонтом, Армстронг даёт 8 м/с вдоль линии визирования — траектория встречи через 130° её орбиты.',
  'watch.beat.terminalPhase': 'Сближение',
  'watch.say.terminalPhase': 'Снова за Луной «Игл» сближается с «Колумбией»; две небольшие коррекции держат его на курсе.',
  'watch.beat.rendezvousBraking': 'Торможение',
