  'watch.beat.cmSeparation': 'Командный модуль один',
  'watch.say.cmSeparation': 'За пятнадцать минут до атмосферы служебный модуль отделяют. Домой возвращается только командный модуль — 3,9 м в поперечнике.',
  'watch.beat.apolloEntry': 'Вход в атмосферу',
