  'watch.beat.apolloSplashdown': 'Приводнение',
  'watch.say.apolloSplashdown': 'Приводнение через 195 часов после старта: над капсулой вертолёты, к ней идёт авианосец «Хорнет».',
  'watch.end.apolloSplashTitle': '«Аполлон-11» дома',
