  'assess.intro': '{n} вопросов из шести разделов, от простых к сложным, без ограничения времени. Вопросы и числа в них выбираются для вас случайно, поэтому тесты не повторяются. Если не знаете ответа, выберите «Не знаю», а не угадывайте: результат нужен, чтобы выбрать, с чего начать, а не для оценки. В части вопросов нужно указать и уверенность в ответе. В таких вопросах верный ответ с пометкой «Угадываю» засчитывается наполовину, а неверный ответ с пометкой «Уверен(а)» отмечается как заблуждение, которое стоит разобрать.',
  'assess.introPost': 'Те же шесть разделов и та же структура, что и во входном тесте, но другие вопросы — чтобы результаты можно было сравнить.',
