  // --- G05 ---
  'setup.mc.title': 'Монте-Карло: точность выведения (G05)',
  'setup.mc.note': 'Много раз пролететь эту миссию в 6-DOF с разбросом двигателей, масс, атмосферы и ветра и увидеть точность выведения — по каждому закону наведения и с указанием, какой разброс определяет рассеивание.',
  'setup.mc.open': 'Открыть окно Монте-Карло',
  'mc.eyebrow': 'G05 · Монте-Карло',
  'mc.title': 'Точность выведения',
  'mc.intro': 'Каждый прогон летит миссию из панели настройки в 6-DOF до её конца — целевой орбиты после всех запланированных включений — со своей выборкой разбросов ниже (нормальное распределение, 1σ по настройке, ограничено 3σ; по каждой ступени и группе боковых блоков). Орбита читается там и в конце активного участка выведения. Миссия рассчитывается по номинальной ракете, летит — ракета с разбросом. Одно и то же зерно даёт одни и те же числа, что бы ни было выключено и какой бы закон ни летел.',
  'mc.mission': '{vehicle}, {site} · целевая орбита {pe} × {ap} км, {inc}° · расчётная орбита выведения {ipe} × {iap} км · 6-DOF · {laws}',
  'mc.settings': 'Настройки',
  'mc.runs': 'Прогонов',
  'mc.seed': 'Зерно',
  'mc.compare': 'Пролететь три закона наведения на одной выборке (втрое больше полётов)',
  'mc.col.quantity': 'Разброс',
  'mc.col.on': 'Вкл.',
  'mc.col.sigma': '1σ',
  'mc.col.unit': 'Единица',
  'mc.q.thrust': 'Тяга',
  'mc.q.thrust.about': 'Тяга каждой ступени и группы боковых блоков; удельный импульс сохраняется, так что расход и время работы следуют за тягой.',
  'mc.q.isp': 'Удельный импульс',
  'mc.q.isp.about': 'Удельный импульс каждой ступени и группы боковых блоков; тяга сохраняется.',
  'mc.q.propellant': 'Заправка топливом',
