  'mc.point.about.final': 'Орбита, на которую доставлен полезный груз после всех запланированных включений, относительно целевой; в 6-DOF — апсиды следующего витка с учётом J2.',
  'mc.point.about.cutoff': 'Орбита в конце активного участка, после спада тяги, относительно расчётной орбиты выведения: точность наведения на участке выведения. Миссия, где выведение завершает верхняя ступень, выключает двигатель раньше намеренно.',
